function projectData(){syncCurrentPattern();return{format:'cs-retro-9000',version:1,exportedAt:new Date().toISOString(),bpm:state.bpm,masterVolume:state.masterVolume,masterFx:ensureMasterFx(),swing:state.swing,humanTiming:state.humanTiming,humanVelocity:state.humanVelocity,clickMode:state.clickMode,clickVolume:state.clickVolume,countInBars:state.countInBars,loopStart:state.loopStart,loopEnd:state.loopEnd,mirrorMode:state.mirrorMode,mirrorBars:state.mirrorBars,mirrorRecord:state.mirrorRecord,tracks:state.tracks,patterns:state.patterns,currentPattern:state.currentPattern,arrangement:state.arrangement,arrangementMeta:state.arrangementMeta,songLoopEnabled:state.songLoopEnabled,songLoopStart:state.songLoopStart,songLoopEnd:state.songLoopEnd,panelVisibility}}
