const loadProjectCore=loadProjectData;
loadProjectData=function(input){state.arrangementMeta=Array.isArray(input.arrangementMeta)?input.arrangementMeta:[];state.mirrorMode=['off','all','custom'].includes(input.mirrorMode)?input.mirrorMode:'off';state.mirrorBars=Array.isArray(input.mirrorBars)?input.mirrorBars:[0,1,2,3,4,5,6,7];state.mirrorRecord=!!input.mirrorRecord;loadProjectCore(input);updateMasterNodes(masterNodes,ensureMasterFx());if(master)master.gain.value=state.masterVolume;state.clickMode=['off','play','record','always'].includes(input.clickMode)?input.clickMode:'off';state.clickVolume=Math.max(0,Math.min(1,input.clickVolume??.45));state.countInBars=[0,1,2,4].includes(+input.countInBars)?+input.countInBars:2;state.songLoopEnabled=!!input.songLoopEnabled;state.songLoopStart=+input.songLoopStart||0;state.songLoopEnd=Number.isFinite(+input.songLoopEnd)?+input.songLoopEnd:Math.max(0,state.arrangement.length-1);normalizeArrangementMeta();updateClickUI();renderPatterns();renderMirrorControls();saveProjectLocal()};
async function importProjectFile(file){try{const text=await file.text(),data=JSON.parse(text);loadProjectData(data);toast(`Opened ${file.name}`);$('#status').textContent='Portable project imported'}catch(error){console.error(error);toast(error instanceof SyntaxError?'Project file is not valid JSON':error.message||'Could not open project')}finally{$('#projectFile').value=''}}
