const midiVlq=value=>{const bytes=[Math.max(0,Math.round(value))&127];for(value=Math.max(0,Math.round(value))>>7;value;value>>=7)bytes.unshift((value&127)|128);return bytes},midiText=value=>[...new TextEncoder().encode(value)],midiU32=value=>[(value>>>24)&255,(value>>>16)&255,(value>>>8)&255,value&255];
