function midiTempoTrack(song,ppq){const events=[{tick:0,bpm:state.bpm}];if(song)state.arrangementMeta.forEach((meta,slot)=>{if(meta?.tempo)events.push({tick:slot*beats()*ppq,bpm:meta.tempo})});events.sort((a,b)=>a.tick-b.tick);let last=0,body=[0,255,3,9,...midiText('CS Retro 9000')];events.forEach(event=>{const micros=Math.round(60000000/event.bpm);body.push(...midiVlq(event.tick-last),255,81,3,(micros>>16)&255,(micros>>8)&255,micros&255);last=event.tick});body.push(0,255,88,4,4,2,24,8,0,255,47,0);return midiChunk('MTrk',body)}function buildMidi(song=false){const ppq=480,conductor=midiTempoTrack(song,ppq),tracks=[];state.tracks.forEach((track,index)=>{const notes=[];if(song)state.arrangement.forEach((id,slot)=>{const pattern=state.patterns.find(p=>p.id===id);(pattern?.tracks[index]||[]).filter(note=>note.start>=state.loopStart&&note.start<state.loopEnd).forEach(note=>notes.push({...note,start:slot*loopLength()+(note.start-state.loopStart),duration:Math.min(note.duration,state.loopEnd-note.start)}))});else track.notes.forEach(note=>notes.push({...note}));const channel=(PRESETS[track.preset]||{}).drumKit?9:index;tracks.push(midiTrackBytes(trackLabel(track,index),notes,channel,ppq))});const header=midiChunk('MThd',[0,1,0,tracks.length+1,(ppq>>8)&255,ppq&255]);return new Uint8Array([...header,...conductor,...tracks])}
function exportMidi(song=false){if(song&&!state.arrangement.length){toast('Add patterns to the song arrangement first');return}const hasNotes=song?state.arrangement.some(id=>{const pattern=state.patterns.find(p=>p.id===id);return pattern?.tracks.some(notes=>notes.length)}):state.tracks.some(track=>track.notes.length);if(!hasNotes){toast('There are no notes to export');return}const bytes=buildMidi(song),stamp=new Date().toISOString().slice(0,19).replace(/[:T]/g,'-');queueExport(new Blob([bytes],{type:'audio/midi'}),`cs-retro-9000-${song?'song':'pattern'}-${stamp}.mid`,song?'Song MIDI saved':'Pattern MIDI saved')}
