function clearLatchedNotes(){[...activeVoices.keys()].filter(key=>key.startsWith('l')).forEach(key=>noteOff(+key.slice(1),key))}
function setLatch(enabled){state.latch=enabled;if(!enabled)clearLatchedNotes();$('#latch').classList.toggle('active',enabled);$('#latch').textContent=`Latch: ${enabled?'On':'Off'}`;toast(enabled?'Latch on — tap notes to build a chord':'Latch off — held notes released')}
function bindMidiInputs(){if(!midiAccess)return;for(const input of midiAccess.inputs.values())input.onmidimessage=e=>{const [status,note,velocity]=e.data,command=status&0xf0,channel=status&0x0f,key=`m${channel}:${note}`;if(command===0x90&&velocity>0)noteOn(note,key,velocity);else if(command===0x80||(command===0x90&&velocity===0))noteOff(note,key)}}
async function connectMidi(){if(!navigator.requestMIDIAccess){toast('Web MIDI is not supported in this browser');return}const button=$('#midi');button.disabled=true;button.textContent='Connecting…';try{midiAccess=await navigator.requestMIDIAccess();bindMidiInputs();midiAccess.onstatechange=()=>{bindMidiInputs();updateMidiButton()};updateMidiButton();toast(midiAccess.inputs.size?`MIDI connected · ${midiAccess.inputs.size} input${midiAccess.inputs.size===1?'':'s'}`:'MIDI enabled — connect a keyboard')}catch(error){button.textContent='Connect MIDI';toast(error?.name==='SecurityError'?'MIDI permission was blocked':'Could not connect MIDI')}finally{button.disabled=false}}
function updateMidiButton(){const count=midiAccess?.inputs.size||0;$('#midi').classList.toggle('active',!!count);$('#midi').textContent=count?`MIDI: ${count} input${count===1?'':'s'}`:'MIDI: Ready'}
function currentSongBeat(){const map=songTempoMap(),startBeat=map.range.start*beats();if(!state.playing)return Math.max(startBeat,Math.min((map.range.end+1)*beats()-.001,state.songPause));const elapsed=((ctx.currentTime-state.startTime)%map.totalSec+map.totalSec)%map.totalSec,entry=[...map.entries].reverse().find(item=>elapsed>=item.startSec)||map.entries[0];return entry.slot*beats()+(elapsed-entry.startSec)*entry.bpm/60}
function currentBeat(){if(state.songMode)return currentSongBeat()%beats();if(!state.playing)return state.pauseBeat;const raw=(ctx.currentTime-state.startTime)*state.bpm/60-state.loopStart;return state.loopStart+((raw%loopLength())+loopLength())%loopLength()}
function scheduleSong(run){if(!state.playing||run!==scheduleRun||!state.arrangement.length)return;const map=songTempoMap(),cycle=map.totalSec,origin=state.startTime,now=ctx.currentTime,from=Math.max(now-.005,scheduleCursor||now),to=now+.24,solo=state.tracks.some(t=>t.solo),first=Math.max(0,Math.floor((from-origin)/cycle)-1),last=Math.max(first,Math.ceil((to-origin)/cycle));map.entries.forEach(entry=>{const pattern=state.patterns.find(p=>p.id===state.arrangement[entry.slot]);if(!pattern)return;state.tracks.forEach((tr,ti)=>{if(tr.mute||(solo&&!tr.solo))return;(pattern.tracks[ti]||[]).slice().sort((a,b)=>a.start-b.start).forEach(n=>{for(let k=first;k<=last;k++){const grooved=grooveBeat(n,ti),at=origin+entry.startSec+grooved*60/entry.bpm+k*cycle,duration=Math.min(n.duration,beats()-n.start)*60/entry.bpm;if(at>=from&&at<to)makeVoice(n.note,ti,at,duration,true,grooveVelocity(n)/127)}})});for(let beat=0;beat<beats();beat++)for(let k=first;k<=last;k++){const at=origin+entry.startSec+beat*60/entry.bpm+k*cycle;if(metronomeEnabled()&&at>=from&&at<to)clickAt(at,beat%4===0)}});scheduleCursor=to;scheduleTimer=setTimeout(()=>scheduleSong(run),90)}
function scheduleLoop(run=scheduleRun){if(state.songMode){scheduleSong(run);return}if(!state.playing||run!==scheduleRun)return;const secondsPerBeat=60/state.bpm,cycle=loopLength()*secondsPerBeat,origin=state.startTime+state.loopStart*secondsPerBeat,now=ctx.currentTime,from=Math.max(now-.005,scheduleCursor||now),to=now+.24,solo=state.tracks.some(t=>t.solo),first=Math.max(0,Math.floor((from-origin)/cycle)-1),last=Math.max(first,Math.ceil((to-origin)/cycle));state.tracks.forEach((tr,ti)=>{if(tr.mute||(solo&&!tr.solo))return;const frozen=frozenTrack(ti);if(frozen){if(!scheduleCursor){const started=origin+Math.floor((now-origin)/cycle)*cycle,offset=Math.max(0,now-started);if(started<from&&offset<frozen.buffer.duration-.01)scheduleFrozenBuffer(frozen.buffer,now+.01,offset)}for(let k=first;k<=last;k++){const at=origin+k*cycle;if(at>=from&&at<to)scheduleFrozenBuffer(frozen.buffer,at)}return}tr.notes.filter(n=>n.start>=state.loopStart&&n.start<state.loopEnd).sort((a,b)=>a.start-b.start).forEach(n=>{for(let k=first;k<=last;k++){const grooved=grooveBeat(n,ti),at=origin+(grooved-state.loopStart)*secondsPerBeat+k*cycle,duration=Math.min(n.duration,state.loopEnd-n.start)*secondsPerBeat;if(at>=from&&at<to)makeVoice(n.note,ti,at,duration,true,grooveVelocity(n)/127)}})});scheduleClickWindow(from,to,origin,cycle,Array.from({length:Math.max(0,Math.ceil(state.loopEnd)-Math.ceil(state.loopStart))},(_,i)=>Math.ceil(state.loopStart)+i-state.loopStart));scheduleCursor=to;scheduleTimer=setTimeout(()=>scheduleLoop(run),90)}
function play(){ensureAudio();if(state.playing){if(state.songMode)state.songPause=currentSongBeat();else state.pauseBeat=currentBeat();state.playing=false;cancelScheduledAudio();cancelAnimationFrame(state.raf);$('#play').textContent='▶ Play';$('#status').textContent='Paused';updateMixerMeters(-999);return}if(state.songMode&&!state.arrangement.length){toast('Add at least one pattern to the song');return}if(state.songMode){const range=songSlotRange(),start=range.start*beats(),end=(range.end+1)*beats();if(state.songPause<start||state.songPause>=end)state.songPause=start}if(!state.songMode&&(state.pauseBeat<state.loopStart||state.pauseBeat>=state.loopEnd))state.pauseBeat=state.loopStart;cancelScheduledAudio();state.startTime=state.songMode?ctx.currentTime-songBeatToSeconds(state.songPause):ctx.currentTime-state.pauseBeat*60/state.bpm;state.playing=true;$('#play').textContent='❚❚ Pause';$('#status').textContent=state.songMode?'Playing song arrangement':state.recording?'Recording… play the keyboard':'Playing pattern loop';scheduleLoop(scheduleRun);animate()}
function animate(){if(!state.playing)return;const b=currentBeat(),x=b/beats()*100;document.querySelectorAll('.playhead').forEach(p=>p.style.left=x+'%');updatePosition(b);updateDrumPlayhead(b);updatePianoRollPlayhead(b);applyAutomation(b);updateMixerMeters(b);if(state.songMode){const global=currentSongBeat(),slot=Math.floor(global/beats());if(slot!==activeSongSlot){activeSongSlot=slot;renderPatterns(slot)}$('#status').textContent=`Playing song · block ${slot+1} of ${state.arrangement.length}`}state.raf=requestAnimationFrame(animate)}
function record(){if(state.songMode){toast('Switch to Pattern Loop mode to record');return}if(state.countingIn){cancelCountIn();return}ensureAudio();if(state.recording){state.recording=false;recordStarts.clear();$('#record').classList.remove('active');$('#record').textContent='● Record';$('#status').textContent='Recording stopped';restartScheduler();return}if(!state.playing&&state.countInBars>0){beginCountIn();return}state.recording=true;$('#record').classList.add('active');$('#record').textContent='■ Recording';if(!state.playing){state.pauseBeat=state.loopStart;play()}else restartScheduler();$('#status').textContent='Recording — play notes'}
