function beginPianoNoteDrag(e,note,el){e.stopPropagation();const add=e.shiftKey||e.ctrlKey||e.metaKey;if(!state.selectedNotes.has(note.id)){if(!add)state.selectedNotes.clear();state.selectedNotes.add(note.id);selectMirrorGroup(note)}else selectMirrorGroup(note);const mode=e.target.classList.contains('piano-resize')?'resize':'move',before=takeSnapshot(),startX=e.clientX,startY=e.clientY,base=new Map();state.tracks[state.selected].notes.forEach(n=>{if(state.selectedNotes.has(n.id))base.set(n.id,{start:n.start,duration:n.duration,note:n.note})});const move=ev=>{const beatDelta=quantize((ev.clientX-startX)/state.pianoZoom),pitchDelta=-Math.round((ev.clientY-startY)/PIANO_ROW);state.tracks[state.selected].notes.forEach(n=>{const b=base.get(n.id);if(!b)return;if(mode==='resize')n.duration=Math.max(state.snap||.05,Math.min(beats()-n.start,b.duration+beatDelta));else{n.start=Math.max(0,Math.min(beats()-b.duration,b.start+beatDelta));n.note=Math.max(PIANO_MIN,Math.min(PIANO_MAX,b.note+pitchDelta))}});renderPianoRoll();renderNotes()};const up=()=>{window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',up);if(before!==takeSnapshot()){undoStack.push({data:before,label:mode==='resize'?'resize piano notes':'move piano notes'});redoStack=[];updateHistoryButtons()}render()};window.addEventListener('pointermove',move);window.addEventListener('pointerup',up,{once:true});renderPianoRoll();updateSelectionInfo()}
function updatePianoRollPlayhead(beat){const head=$('#pianoPlayhead');if(head)head.style.left=beat*state.pianoZoom+'px'}
function centerPianoRoll(){const scroller=$('#pianoScroll'),notes=state.tracks[state.selected].notes;if(!scroller)return;const pitch=notes.length?notes.reduce((sum,n)=>sum+n.note,0)/notes.length:60,top=(PIANO_MAX-pitch)*PIANO_ROW-scroller.clientHeight/2;scroller.scrollTop=Math.max(0,top);scroller.scrollLeft=Math.max(0,state.pauseBeat*state.pianoZoom-scroller.clientWidth/3)}
const DRUM_ROWS=[['Kick',48],['Snare',50],['Clap',51],['Closed Hat',52],['Low Tom',53],['Mid Tom',54],['High Tom',55],['Open Hat',59]];
function ensureSelectedDrumKit(){const track=state.tracks[state.selected];if((PRESETS[track.preset]||{}).drumKit)return;track.preset='16-Bit Console Kit';track.sound=defaultSound(track.preset);$('#bank').value='Drums';$('#presetSearch').value='';populatePresets()}
function renderDrumSequencer(){const root=$('#drumGrid'),barSelect=$('#drumBar');if(!root||!barSelect)return;if(!barSelect.options.length){for(let i=0;i<state.bars;i++)barSelect.add(new Option(`Bar ${i+1}`,i))}state.drumBar=Math.max(0,Math.min(state.bars-1,state.drumBar));barSelect.value=state.drumBar;root.innerHTML='';const track=state.tracks[state.selected],base=state.drumBar*4;DRUM_ROWS.forEach(([name,note])=>{const label=document.createElement('div');label.className='drum-label';label.textContent=name;root.append(label);for(let step=0;step<16;step++){const start=base+step*.25,on=track.notes.some(n=>n.note===note&&Math.abs(n.start-start)<.001),button=document.createElement('button');button.className='drum-step'+(on?' on':'');button.title=`${name} · step ${step+1}`;button.setAttribute('aria-label',`${name}, step ${step+1}${on?', active':''}`);button.onclick=()=>toggleDrumStep(note,start);root.append(button)}});$('#useDrumKit').textContent=(PRESETS[track.preset]||{}).drumKit?'16-Bit Kit Active':'Use 16-Bit Kit';$('#useDrumKit').classList.toggle('active',(PRESETS[track.preset]||{}).drumKit)}
