function updateDrumPlayhead(beat){const local=((beat-state.drumBar*4)%4+4)%4,step=Math.floor(local/.25);document.querySelectorAll('.drum-step').forEach((el,i)=>el.classList.toggle('playing',i%16===step))}
function clearDrumBar(){const track=state.tracks[state.selected],start=state.drumBar*4,end=start+4,drumNotes=new Set(DRUM_ROWS.map(row=>row[1]));if(!track.notes.some(n=>drumNotes.has(n.note)&&n.start>=start&&n.start<end)){toast('This drum bar is already empty');return}remember('clear drum bar');track.notes=track.notes.filter(n=>!drumNotes.has(n.note)||n.start<start||n.start>=end);const pattern=state.patterns.find(p=>p.id===state.currentPattern);if(pattern)pattern.tracks[state.selected]=track.notes;render();restartScheduler();toast(`Cleared drum bar ${state.drumBar+1}`)}
function randomizeDrums(){const track=state.tracks[state.selected],start=state.drumBar*4,end=start+4,drumNotes=new Set(DRUM_ROWS.map(row=>row[1]));remember('randomize drums');ensureSelectedDrumKit();track.notes=track.notes.filter(n=>!drumNotes.has(n.note)||n.start<start||n.start>=end);for(let step=0;step<16;step++){const at=start+step*.25;if(step%4===0||Math.random()<.14)track.notes.push({id:uid(),note:48,start:at,duration:.18,velocity:112});if(step%8===4||Math.random()<.09)track.notes.push({id:uid(),note:50,start:at,duration:.18,velocity:112});if(step%2===0||Math.random()<.38)track.notes.push({id:uid(),note:52,start:at,duration:.12,velocity:82});if(Math.random()<.08)track.notes.push({id:uid(),note:59,start:at,duration:.22,velocity:96})}const pattern=state.patterns.find(p=>p.id===state.currentPattern);if(pattern)pattern.tracks[state.selected]=track.notes;render();restartScheduler();toast(`Randomized drum bar ${state.drumBar+1}`)}
function renderRuler(){const r=$('#ruler');r.innerHTML=Array.from({length:8},(_,i)=>`<span>${i+1}</span>`).join('');r.onpointerdown=e=>seekFromEvent(e,r);const region=document.createElement('div');region.className='loop-region';region.innerHTML='<i class="loop-handle start"></i><i class="loop-handle end"></i>';r.append(region);bindLoopRegion(region);updateLoopUI()}
const AUTOMATION={volume:{min:0,max:1,label:'VOLUME'},pan:{min:-1,max:1,label:'PAN'},brightness:{min:300,max:16000,label:'BRIGHTNESS'},resonance:{min:0,max:18,label:'RESONANCE'},fm:{min:0,max:2.5,label:'FM AMOUNT'},detune:{min:0,max:40,label:'DETUNE'},attack:{min:.001,max:1.5,label:'ATTACK'},release:{min:.05,max:4,label:'RELEASE'},glide:{min:0,max:.5,label:'GLIDE'},reverb:{min:0,max:1,label:'REVERB'},distortion:{min:0,max:1,label:'DISTORTION'},bassBoost:{min:0,max:18,label:'BASS BOOST'},phaser:{min:0,max:1,label:'PHASER'},delay:{min:0,max:1,label:'DELAY'},chorus:{min:0,max:1,label:'CHORUS'},crusher:{min:0,max:1,label:'BIT CRUSHER'}};
function ensureAutomation(track){if(!track.automation)track.automation={};Object.keys(AUTOMATION).forEach(key=>{if(!Array.isArray(track.automation[key]))track.automation[key]=[]})}
function automationAt(track,key,beat){ensureAutomation(track);const points=track.automation[key].slice().sort((a,b)=>a.beat-b.beat);if(!points.length)return null;if(beat<=points[0].beat)return points[0].value;if(beat>=points.at(-1).beat)return points.at(-1).value;const right=points.find(p=>p.beat>=beat),left=points[points.indexOf(right)-1],amount=(beat-left.beat)/(right.beat-left.beat);return left.value+(right.value-left.value)*amount}
function automationRatio(key,value){const c=AUTOMATION[key];return(value-c.min)/(c.max-c.min)}
function automationValue(key,ratio){const c=AUTOMATION[key];return c.min+Math.max(0,Math.min(1,ratio))*(c.max-c.min)}
function formatAutomation(key,value){if(key==='brightness')return`${Math.round(value/100)/10}kHz`;if(key==='pan')return mixPanLabel(value);if(['attack','release','glide'].includes(key))return`${value.toFixed(key==='glide'?3:2)}s`;if(key==='detune')return`${value.toFixed(1)}ct`;if(key==='bassBoost')return`+${value.toFixed(1)}dB`;if(['resonance','fm'].includes(key))return value.toFixed(1);return`${Math.round(value*100)}%`}
function renderAutomation(){document.querySelectorAll('.automation-layer').forEach(layer=>layer.remove());$('#automationMode').textContent=`Automation: ${state.automationMode?'On':'Off'}`;$('#automationMode').classList.toggle('active',state.automationMode);$('#automationTarget').value=state.automationTarget;if(!state.automationMode)return;document.querySelectorAll('.lane').forEach((lane,index)=>{const track=state.tracks[index];ensureAutomation(track);const key=state.automationTarget,points=track.automation[key].slice().sort((a,b)=>a.beat-b.beat),layer=document.createElement('div');layer.className='automation-layer active';layer.style.setProperty('--track',trackColor(track,index));const svg=document.createElementNS('http://www.w3.org/2000/svg','svg'),line=document.createElementNS('http://www.w3.org/2000/svg','polyline');svg.classList.add('automation-svg');line.classList.add('automation-line');line.setAttribute('points',points.map(p=>`${p.beat/beats()*100},${(1-automationRatio(key,p.value))*100}`).join(' '));line.setAttribute('vector-effect','non-scaling-stroke');svg.setAttribute('viewBox','0 0 100 100');svg.setAttribute('preserveAspectRatio','none');svg.append(line);layer.append(svg);const badge=document.createElement('span');badge.className='automation-badge';badge.textContent=AUTOMATION[key].label;layer.append(badge);const readout=document.createElement('span');readout.className='automation-value';readout.textContent=points.length?`${points.length} point${points.length===1?'':'s'}`:'Double-click to add points';layer.append(readout);points.forEach(point=>{const dot=document.createElement('i');dot.className='automation-point';dot.style.left=point.beat/beats()*100+'%';dot.style.top=(1-automationRatio(key,point.value))*100+'%';dot.title=`${positionLabel(point.beat)} · ${formatAutomation(key,point.value)}`;dot.onpointerdown=e=>beginAutomationDrag(e,index,point,lane);dot.ondblclick=e=>{e.stopPropagation();remember('delete automation point');track.automation[key]=track.automation[key].filter(p=>p.id!==point.id);renderAutomation();restartScheduler()};layer.append(dot)});layer.ondblclick=e=>{if(e.target.classList.contains('automation-point'))return;const r=lane.getBoundingClientRect(),beat=Math.max(0,Math.min(beats(),quantize((e.clientX-r.left)/r.width*beats()))),value=automationValue(key,1-(e.clientY-r.top)/r.height);remember('add automation point');track.automation[key].push({id:uid(),beat,value});track.automation[key].sort((a,b)=>a.beat-b.beat);renderAutomation();toast(`${AUTOMATION[key].label} point · ${formatAutomation(key,value)}`)};lane.append(layer)})}
function beginAutomationDrag(e,trackIndex,point,lane){e.stopPropagation();const before=takeSnapshot(),key=state.automationTarget,r=lane.getBoundingClientRect();const move=ev=>{point.beat=Math.max(0,Math.min(beats(),quantize((ev.clientX-r.left)/r.width*beats())));point.value=automationValue(key,1-(ev.clientY-r.top)/r.height);state.tracks[trackIndex].automation[key].sort((a,b)=>a.beat-b.beat);renderAutomation()};const up=()=>{window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',up);if(before!==takeSnapshot()){undoStack.push({data:before,label:'move automation point'});redoStack=[];updateHistoryButtons()}renderAutomation();restartScheduler()};window.addEventListener('pointermove',move);window.addEventListener('pointerup',up,{once:true})}
function applyAutomation(beat){const local=((beat%beats())+beats())%beats();state.tracks.forEach((track,index)=>{ensureAutomation(track);const sound=soundFor(track);Object.keys(AUTOMATION).forEach(key=>{const value=automationAt(track,key,local);if(value==null)return;if(key==='volume')track.volume=value;else sound[key]=value;const mixInput=document.querySelector(`.mixer-strip[data-track="${index}"] [data-mix="${key}"]`);if(mixInput){mixInput.value=value;mixInput.parentElement.querySelector('output').textContent=key==='pan'?mixPanLabel(value):Math.round(value*100)}})});const selected=state.tracks[state.selected],selectedSound=soundFor(selected);$('#volume').value=selected.volume;document.querySelectorAll('[data-sound]').forEach(input=>{if(Object.prototype.hasOwnProperty.call(AUTOMATION,input.dataset.sound)){input.value=selectedSound[input.dataset.sound];updateSoundOutput(input)}})}
function renderTracks(){syncCurrentPattern();const controls=$('#trackControls'),lanes=$('#lanes');controls.innerHTML='';lanes.innerHTML='';state.tracks.forEach((tr,i)=>{const frozen=!!frozenTrack(i),c=document.createElement('div');c.className='track-card'+(i===state.selected?' selected':'')+(frozen?' frozen':'');c.style.setProperty('--track',trackColor(tr,i));c.innerHTML=`<span class="track-num">${i+1}</span><div><div class="track-title">${escapeHtml(trackLabel(tr,i))}${frozen?'<span class="freeze-badge">FROZEN</span>':''}</div><div class="track-sub">${escapeHtml(tr.preset)} · ${tr.notes.length} notes</div></div><div class="mini-buttons"><button data-act="mute" class="${tr.mute?'on':''}">M</button><button data-act="solo" class="${tr.solo?'on':''}">S</button></div>`;c.onclick=e=>{if(e.target.dataset.act){tr[e.target.dataset.act]=!tr[e.target.dataset.act];renderTracks();return}state.selected=i;state.selectedNotes.clear();render()};controls.append(c);const l=document.createElement('div');l.className='lane';l.dataset.track=i;l.style.setProperty('--track',trackColor(tr,i));l.innerHTML='<div class="barline"></div><div class="playhead" style="left:0"></div>';l.onpointerdown=e=>{if(e.target===l||e.target.classList.contains('barline')){state.selected=i;if(!e.shiftKey&&!e.ctrlKey&&!e.metaKey)state.selectedNotes.clear();seekFromEvent(e,l);render()}};lanes.append(l)});renderNotes();bindPlayheads();document.querySelectorAll('.playhead').forEach(p=>p.style.left=(state.pauseBeat/beats()*100)+'%')}
function renderNotes(){document.querySelectorAll('.lane').forEach((lane,i)=>{lane.querySelectorAll('.note').forEach(n=>n.remove());state.tracks[i].notes.forEach(n=>{n.id=n.id||uid();const el=document.createElement('span');el.className='note'+(state.selectedNotes.has(n.id)?' selected':'');el.dataset.id=n.id;if(n.mirrorGroup)el.dataset.mirror=n.mirrorGroup;el.style.left=(n.start/beats()*100)+'%';el.style.width=(n.duration/beats()*100)+'%';el.style.opacity=.35+.65*(n.velocity??100)/127;el.style.bottom=(6+(n.note-36)/60*50)+'px';el.title=`${midiName(n.note)} · velocity ${n.velocity??100} · bar ${Math.floor(n.start/4)+1}, beat ${(n.start%4+1).toFixed(2)}`;el.innerHTML='<i class="note-handle left"></i><i class="note-handle right"></i>';el.onpointerdown=e=>beginNoteDrag(e,i,n,el);lane.append(el)})});updateSelectionInfo();renderPianoRoll();renderAutomation()}
function seekFromEvent(e,el){const r=el.getBoundingClientRect(),b=Math.max(state.loopStart,Math.min(state.loopEnd-.001,(e.clientX-r.left)/r.width*beats()));state.pauseBeat=Math.max(state.loopStart,Math.min(state.loopEnd-.001,quantize(b)));if(state.playing){state.startTime=ctx.currentTime-state.pauseBeat*60/state.bpm;restartScheduler()}updatePosition(state.pauseBeat);document.querySelectorAll('.playhead').forEach(p=>p.style.left=(state.pauseBeat/beats()*100)+'%')}
function updatePosition(b){const bar=Math.floor(b/4)+1,beat=Math.floor(b%4)+1,tick=Math.floor((b%1)*4)+1;$('#position').textContent=`${bar}.${beat}.${tick}`}
