function updateLoopUI(){const left=state.loopStart/beats()*100,right=state.loopEnd/beats()*100,region=$('.loop-region');if(region){region.style.left=left+'%';region.style.width=(right-left)+'%'}const lanes=$('#lanes');if(lanes){let leftShade=lanes.querySelector('.loop-shade.left'),rightShade=lanes.querySelector('.loop-shade.right');if(!leftShade){leftShade=document.createElement('div');leftShade.className='loop-shade left';lanes.append(leftShade)}if(!rightShade){rightShade=document.createElement('div');rightShade.className='loop-shade right';lanes.append(rightShade)}leftShade.style.width=left+'%';rightShade.style.width=(100-right)+'%'}if($('#loopInfo'))$('#loopInfo').textContent=`↻ ${positionLabel(state.loopStart)} → ${positionLabel(state.loopEnd)}`}
function bindLoopRegion(region){region.onpointerdown=e=>{e.stopPropagation();const mode=e.target.classList.contains('start')?'start':e.target.classList.contains('end')?'end':'move',r=$('#ruler').getBoundingClientRect(),startX=e.clientX,baseStart=state.loopStart,baseEnd=state.loopEnd,min=state.snap||.25;const move=ev=>{const delta=quantize((ev.clientX-startX)/r.width*beats());if(mode==='start')state.loopStart=Math.max(0,Math.min(baseEnd-min,baseStart+delta));else if(mode==='end')state.loopEnd=Math.min(beats(),Math.max(baseStart+min,baseEnd+delta));else{const length=baseEnd-baseStart,next=Math.max(0,Math.min(beats()-length,baseStart+delta));state.loopStart=next;state.loopEnd=next+length}state.pauseBeat=Math.max(state.loopStart,Math.min(state.loopEnd-.001,state.pauseBeat));updateLoopUI();updatePosition(state.pauseBeat);document.querySelectorAll('.playhead').forEach(p=>p.style.left=(state.pauseBeat/beats()*100)+'%')};const up=()=>{window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',up);if(state.playing)state.startTime=ctx.currentTime-state.pauseBeat*60/state.bpm;restartScheduler();toast(`Loop ${positionLabel(state.loopStart)} → ${positionLabel(state.loopEnd)}`)};window.addEventListener('pointermove',move);window.addEventListener('pointerup',up,{once:true})}}
function bindPlayheads(){document.querySelectorAll('.playhead').forEach(p=>p.onpointerdown=e=>{e.stopPropagation();p.setPointerCapture(e.pointerId);const lane=p.parentElement;p.onpointermove=ev=>seekFromEvent(ev,lane);p.onpointerup=()=>{p.onpointermove=null;p.onpointerup=null}});bindMarquee()}
function bindMarquee(){document.querySelectorAll('.lane').forEach((lane,trackIndex)=>lane.onpointerdown=e=>{if(e.target!==lane&&!e.target.classList.contains('barline'))return;const lanes=$('#lanes'),box=lanes.getBoundingClientRect(),startX=e.clientX,startY=e.clientY,add=e.shiftKey||e.ctrlKey||e.metaKey,prior=new Set(add?state.selectedNotes:[]);let moved=false,marquee;const move=ev=>{if(Math.hypot(ev.clientX-startX,ev.clientY-startY)<5&&!moved)return;moved=true;if(!marquee){marquee=document.createElement('div');marquee.className='marquee';lanes.append(marquee)}const left=Math.max(0,Math.min(startX,ev.clientX)-box.left),top=Math.max(0,Math.min(startY,ev.clientY)-box.top),right=Math.min(box.width,Math.max(startX,ev.clientX)-box.left),bottom=Math.min(box.height,Math.max(startY,ev.clientY)-box.top);Object.assign(marquee.style,{left:left+'px',top:top+'px',width:Math.max(1,right-left)+'px',height:Math.max(1,bottom-top)+'px'});state.selectedNotes=new Set(prior);document.querySelectorAll('.note').forEach(el=>{const r=el.getBoundingClientRect(),hit=r.right>=box.left+left&&r.left<=box.left+right&&r.bottom>=box.top+top&&r.top<=box.top+bottom;if(hit)state.selectedNotes.add(el.dataset.id);el.classList.toggle('selected',state.selectedNotes.has(el.dataset.id))});updateSelectionInfo()};const up=ev=>{window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',up);marquee?.remove();if(!moved){state.selected=trackIndex;if(!add)state.selectedNotes.clear();seekFromEvent(ev,lane);render()}else{renderNotes();updateInstrument()}};window.addEventListener('pointermove',move);window.addEventListener('pointerup',up,{once:true})})}
function copySelectedNotes(silent=false){const picked=[];state.tracks.forEach((track,trackIndex)=>track.notes.forEach(n=>{if(state.selectedNotes.has(n.id))picked.push({trackIndex,note:n.note,start:n.start,duration:n.duration,velocity:n.velocity??100})}));if(!picked.length){toast('Select notes to copy');return false}const minStart=Math.min(...picked.map(x=>x.start)),minTrack=Math.min(...picked.map(x=>x.trackIndex));noteClipboard=picked.map(x=>({trackOffset:x.trackIndex-minTrack,startOffset:x.start-minStart,note:x.note,duration:x.duration,velocity:x.velocity}));updateSelectionInfo();if(!silent)toast(`Copied ${picked.length} note${picked.length===1?'':'s'}`);return true}
function cutSelectedNotes(){if(!copySelectedNotes(true))return;const count=state.selectedNotes.size;remember('cut notes');state.tracks.forEach(t=>t.notes=t.notes.filter(n=>!state.selectedNotes.has(n.id)));state.selectedNotes.clear();renderTracks();restartScheduler();toast(`Cut ${count} note${count===1?'':'s'} — move the playhead and paste`)}
function pasteCopiedNotes(){if(!noteClipboard.length){toast('Nothing copied yet');return}remember('paste notes');const maxOffset=Math.max(...noteClipboard.map(x=>x.trackOffset)),baseTrack=Math.min(state.selected,state.tracks.length-1-maxOffset),anchor=quantize(state.pauseBeat);state.selectedNotes.clear();noteClipboard.forEach(x=>{const id=uid(),trackIndex=Math.max(0,Math.min(state.tracks.length-1,baseTrack+x.trackOffset)),start=Math.max(0,Math.min(beats()-x.duration,anchor+x.startOffset));state.tracks[trackIndex].notes.push({id,note:x.note,start,duration:x.duration,velocity:x.velocity??100});state.selectedNotes.add(id)});renderTracks();restartScheduler();toast(`Pasted ${noteClipboard.length} note${noteClipboard.length===1?'':'s'} at ${$('#position').textContent}`)}
function beginNoteDrag(e,ti,n,el){e.stopPropagation();const add=e.shiftKey||e.ctrlKey||e.metaKey;if(!state.selectedNotes.has(n.id)){if(!add)state.selectedNotes.clear();state.selectedNotes.add(n.id);selectMirrorGroup(n)}else if(add&&e.target===el){state.selectedNotes.delete(n.id);renderNotes();return}else selectMirrorGroup(n);state.selected=ti;const mode=e.target.classList.contains('left')?'left':e.target.classList.contains('right')?'right':'move',label=mode==='move'?'move notes':'resize notes',before=takeSnapshot(),lane=el.parentElement,startX=e.clientX,base=new Map();state.tracks.forEach(t=>t.notes.forEach(x=>{if(state.selectedNotes.has(x.id))base.set(x.id,{start:x.start,duration:x.duration})}));const move=ev=>{const delta=quantize((ev.clientX-startX)/lane.getBoundingClientRect().width*beats());state.tracks.forEach(t=>t.notes.forEach(x=>{const b=base.get(x.id);if(!b)return;if(mode==='move')x.start=Math.max(0,Math.min(beats()-b.duration,b.start+delta));if(mode==='right')x.duration=Math.max(state.snap||.05,Math.min(beats()-x.start,b.duration+delta));if(mode==='left'){const end=b.start+b.duration,newStart=Math.max(0,Math.min(end-(state.snap||.05),b.start+delta));x.start=newStart;x.duration=end-newStart}}));renderNotes()};const up=()=>{window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',up);if(before!==takeSnapshot()){undoStack.push({data:before,label});redoStack=[];updateHistoryButtons()}renderTracks()};window.addEventListener('pointermove',move);window.addEventListener('pointerup',up,{once:true});renderNotes();updateInstrument()}
function selectedNoteObjects(){const notes=[];state.tracks.forEach(track=>track.notes.forEach(n=>{if(state.selectedNotes.has(n.id))notes.push(n)}));return notes}
let velocityEditBefore=null;
function setSelectedVelocity(value){const velocity=Math.max(1,Math.min(127,Math.round(value)));selectedNoteObjects().forEach(n=>n.velocity=velocity);$('#velocityValue').textContent=velocity;renderNotes();restartScheduler()}
function updateSelectionInfo(){const n=state.selectedNotes.size,velocity=$('#noteVelocity'),value=$('#velocityValue'),picked=selectedNoteObjects();$('#selectionInfo').textContent=n?`${n} note${n===1?'':'s'} selected`:'No notes selected';if(velocity){velocity.disabled=!n;if(n){const values=[...new Set(picked.map(note=>note.velocity??100))],shown=values.length===1?values[0]:Math.round(picked.reduce((sum,note)=>sum+(note.velocity??100),0)/picked.length);velocity.value=shown;value.textContent=values.length===1?shown:'Mix'}}if($('#cutNotes'))$('#cutNotes').disabled=!n;if($('#copyNotes'))$('#copyNotes').disabled=!n;if($('#pasteNotes'))$('#pasteNotes').disabled=!noteClipboard.length}
function renderKeyboard(){const root=$('#keyboard'),drums=(PRESETS[state.tracks[state.selected].preset]||{}).drumKit;root.innerHTML='';for(let n=state.octave*12+12;n<state.octave*12+36;n++){const pc=n%12;if([1,3,6,8,10].includes(pc))continue;addKey(n,false);if(![4,11].includes(pc)&&n+1<state.octave*12+36)addKey(n+1,true)}function addKey(n,black){const k=document.createElement('div');k.className='key'+(black?' black':'');if(activeVoices.has('l'+n))k.classList.add('playing');k.dataset.note=n;k.textContent=drums?DRUM_NAMES[n%12]:midiName(n);k.onpointerdown=e=>{e.preventDefault();k.setPointerCapture(e.pointerId);state.latch?toggleLatchedNote(n):noteOn(n,'p'+e.pointerId)};k.onpointerup=e=>{if(!state.latch)noteOff(n,'p'+e.pointerId)};k.onpointercancel=e=>{if(!state.latch)noteOff(n,'p'+e.pointerId)};root.append(k)}}
