function updateInstrument(){const tr=state.tracks[state.selected],s=soundFor(tr),drums=(PRESETS[tr.preset]||{}).drumKit;document.documentElement.style.setProperty('--track',trackColor(tr,state.selected));$('#activeName').textContent=`${state.selected+1} · ${trackLabel(tr,state.selected)} · ${tr.preset}`;if(![...$('#preset').options].some(o=>o.value===tr.preset)){if($('#presetSearch'))$('#presetSearch').value='';$('#bank').value=classFor(tr.preset)||'Universal';populatePresets()}$('#preset').value=tr.preset;$('#trackName').value=trackLabel(tr,state.selected);$('#trackColor').value=trackColor(tr,state.selected);$('#volume').value=tr.volume;const frozen=!!frozenTrack(state.selected);$('#freezeTrack').textContent=frozen?'Unfreeze Track':'Freeze Track';$('#freezeTrack').classList.toggle('active',frozen);$('#octave').textContent=state.octave;$('#drumLegend').hidden=!drums;document.querySelectorAll('[data-sound]').forEach(input=>{input.value=s[input.dataset.sound];updateSoundOutput(input)});updateLoopUI()}
function updateSoundOutput(input){const value=+input.value,key=input.dataset.sound,out=input.parentElement.querySelector('output');out.textContent=key==='brightness'?`${Math.round(value/100)/10}kHz`:key==='detune'?`${value}ct`:key==='attack'||key==='release'||key==='glide'?`${value.toFixed(key==='glide'?3:2)}s`:key==='bassBoost'?`+${value.toFixed(1)}dB`:['eqLow','eqMid','eqHigh'].includes(key)?`${value>0?'+':''}${value.toFixed(1)}dB`:key==='compThreshold'?`${Math.round(value)}dB`:key==='compRatio'?`${value.toFixed(1)}:1`:key==='compMakeup'?`+${value.toFixed(1)}dB`:key==='pan'?(Math.abs(value)<.01?'Center':`${Math.round(Math.abs(value)*100)}${value<0?'L':'R'}`):['reverb','distortion','phaser','delay','chorus','crusher'].includes(key)?`${Math.round(value*100)}%`:value.toFixed(1)}
