$('#preset').onchange=e=>{if(!e.target.value||state.tracks[state.selected].preset===e.target.value){e.target.blur();return}remember('change sound');state.tracks[state.selected].preset=e.target.value;state.tracks[state.selected].sound=defaultSound(e.target.value);e.target.blur();render()};
document.querySelectorAll('[data-sound]').forEach(input=>input.oninput=()=>{soundFor(state.tracks[state.selected])[input.dataset.sound]=+input.value;updateSoundOutput(input)});$('#resetSound').onclick=()=>{state.tracks[state.selected].sound=defaultSound(state.tracks[state.selected].preset);updateInstrument();toast('Preset controls reset')};
