const keyMap={a:0,w:1,s:2,e:3,d:4,f:5,t:6,g:7,y:8,h:9,u:10,j:11,k:12,l:13},isTyping=e=>e.target.matches('input,textarea,select,button,[contenteditable="true"]');
function changeOctave(step){const next=Math.max(2,Math.min(6,state.octave+step));if(next===state.octave)return;state.octave=next;renderKeyboard();updateInstrument();toast(`Octave ${state.octave}`)}
function cyclePreset(step){const instrumentClass=$('#bank').value,names=Object.keys(PRESETS).filter(name=>matchesClass(name,instrumentClass));if(!names.length)return;let current=names.indexOf(state.tracks[state.selected].preset);if(current<0)current=step>0?-1:0;const nextIndex=(current+step+names.length)%names.length,wrapped=step>0&&nextIndex===0||step<0&&nextIndex===names.length-1,next=names[nextIndex];remember('change sound');state.tracks[state.selected].preset=next;state.tracks[state.selected].sound=defaultSound(next);$('#presetSearch').value='';populatePresets();render();toast(`${wrapped?'Wrapped · ':''}${next}`)}
function cycleTrack(step){state.selected=(state.selected+step+state.tracks.length)%state.tracks.length;state.selectedNotes.clear();render();toast(`Track ${state.selected+1}: ${state.tracks[state.selected].preset}`)}
window.onkeydown=e=>{if(e.code==='F9'){e.preventDefault();if(!e.repeat)record();return}const key=e.key.toLowerCase();if(key==='l'&&e.metaKey){toast('Windows key detected — Win+L locks Windows');return}if(isTyping(e)||e.ctrlKey||e.metaKey||e.altKey||e.repeat)return;if(key==='z'){e.preventDefault();changeOctave(-1);return}if(key==='x'){e.preventDefault();changeOctave(1);return}if(e.key==='ArrowUp'){e.preventDefault();cyclePreset(-1);return}if(e.key==='ArrowDown'){e.preventDefault();cyclePreset(1);return}if(e.key==='ArrowLeft'){e.preventDefault();cycleTrack(-1);return}if(e.key==='ArrowRight'){e.preventDefault();cycleTrack(1);return}const off=keyMap[key];if(off!=null){e.preventDefault();const note=state.octave*12+12+off;state.latch?toggleLatchedNote(note):noteOn(note,'k'+key)}if(e.code==='Space'){e.preventDefault();play()}};window.onkeyup=e=>{const key=e.key.toLowerCase(),off=keyMap[key];if(off!=null&&!state.latch)noteOff(state.octave*12+12+off,'k'+key)};
document.addEventListener('keydown',e=>{if(!(e.ctrlKey||e.metaKey)||e.target.matches('input,select'))return;const k=e.key.toLowerCase();if(k==='z'){e.preventDefault();e.stopImmediatePropagation();e.shiftKey?redo():undo()}else if(k==='y'){e.preventDefault();e.stopImmediatePropagation();redo()}},true);
document.addEventListener('keydown',e=>{if(!(e.ctrlKey||e.metaKey)||isTyping(e))return;const k=e.key.toLowerCase();if(k==='x'){e.preventDefault();e.stopImmediatePropagation();cutSelectedNotes()}else if(k==='c'){e.preventDefault();e.stopImmediatePropagation();copySelectedNotes()}else if(k==='v'){e.preventDefault();e.stopImmediatePropagation();pasteCopiedNotes()}},true);
document.addEventListener('keydown',e=>{if((e.key!=='Delete'&&e.key!=='Backspace')||!state.selectedNotes.size||e.target.matches('input,select'))return;e.preventDefault();e.stopImmediatePropagation();remember('delete notes');state.tracks.forEach(t=>t.notes=t.notes.filter(n=>!state.selectedNotes.has(n.id)));state.selectedNotes.clear();renderTracks();toast('Selected notes removed')},true);
try{const saved=JSON.parse(localStorage.getItem('fm-loop-studio'));if(saved?.tracks?.length===5){state.bpm=saved.bpm||110;state.masterVolume=Math.max(0,Math.min(1,saved.masterVolume??.82));state.masterFx=saved.masterFx&&typeof saved.masterFx==='object'?{...saved.masterFx}:null;ensureMasterFx();state.swing=Math.max(0,Math.min(75,saved.swing??0));state.humanTiming=Math.max(0,Math.min(30,saved.humanTiming??0));state.humanVelocity=Math.max(0,Math.min(25,saved.humanVelocity??0));state.mirrorMode=['off','all','custom'].includes(saved.mirrorMode)?saved.mirrorMode:'off';state.mirrorBars=Array.isArray(saved.mirrorBars)?saved.mirrorBars:[0,1,2,3,4,5,6,7];state.mirrorRecord=!!saved.mirrorRecord;state.clickMode=['off','play','record','always'].includes(saved.clickMode)?saved.clickMode:'off';state.clickVolume=Math.max(0,Math.min(1,saved.clickVolume??.45));state.countInBars=[0,1,2,4].includes(+saved.countInBars)?+saved.countInBars:2;state.loopStart=Math.max(0,Math.min(beats()-.25,saved.loopStart??0));state.loopEnd=Math.max(state.loopStart+.25,Math.min(beats(),saved.loopEnd??beats()));state.pauseBeat=state.loopStart;state.tracks=saved.tracks;if(Array.isArray(saved.patterns)&&saved.patterns.length){state.patterns=saved.patterns;state.currentPattern=saved.currentPattern;state.arrangement=Array.isArray(saved.arrangement)?saved.arrangement:[];state.arrangementMeta=Array.isArray(saved.arrangementMeta)?saved.arrangementMeta:[];state.songLoopEnabled=!!saved.songLoopEnabled;state.songLoopStart=+saved.songLoopStart||0;state.songLoopEnd=Number.isFinite(+saved.songLoopEnd)?+saved.songLoopEnd:Math.max(0,state.arrangement.length-1)}$('#bpm').value=state.bpm}}catch{}state.tracks.forEach((t,index)=>{ensureTrackIdentity(t,index);if(!PRESETS[t.preset])t.preset='Neon Keys';soundFor(t);ensureAutomation(t);ensureGroove(t);t.notes.forEach(n=>{n.id=n.id||uid();n.velocity=Math.max(1,Math.min(127,n.velocity??100))})});ensurePatterns();state.patterns.forEach(p=>{p.tracks=Array.from({length:5},(_,i)=>p.tracks?.[i]||[]);p.tracks.forEach(notes=>notes.forEach(n=>{n.id=n.id||uid();n.velocity=Math.max(1,Math.min(127,n.velocity??100))}))});bindPattern(state.currentPattern,false);populatePresets();render();renderPatterns();updateHistoryButtons();initPanelSwitcher();updateClickUI();
